Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

#define F first
#define S second
#define MP make_pair
#define all(x) (x).begin(), (x).end()

typedef long long ll;
typedef unsigned long long ull;
typedef long double ld;

const double EPS = 1e-9;
const double PI = acos(-1.0);
const int MOD = 1000 * 1000 * 1000 + 7;
const int INF = 2000 * 1000 * 1000;
const int MAXN = 210;
const int MAXM = 2 * MAXN * MAXN;
const int dx[] = {1, 0, 0, -1};
const int dy[] = {0, 1, -1, 0};
const int S = MAXN - 2;
const int T = MAXN - 1;

template <typename T>
inline T sqr(T n) {
    return n * n;
}

struct MaxFlow {
    int to[MAXM];
    int flow[MAXM], cap[MAXM];
    int lastEdge;
    vector<int> g[MAXN];
    int level[MAXN], ptr[MAXN];

    MaxFlow() : lastEdge(0) {}

    void addEdge(int from, int to, int cap) {
        this->to[lastEdge] = to;
        this->flow[lastEdge] = 0;
        this->cap[lastEdge] = cap;
        g[from].push_back(lastEdge++);

        this->to[lastEdge] = from;
        this->flow[lastEdge] = 0;
        this->cap[lastEdge] = 0;
        g[to].push_back(lastEdge++);
    }

    bool bfs(int s, int t) {
        memset(level, -1, sizeof level);
        queue<int> q;
        level[s] = 0;
        q.push(s);
        while (!q.empty()) {
            int v = q.front(); q.pop();
            for (int idx : g[v]) {
                if (level[to[idx]] == -1 && cap[idx] - flow[idx] > 0) {
                    level[to[idx]] = level[v] + 1;
                    q.push(to[idx]);
                }
            }
        }
        return level[t] != -1;
    }

    int dfs(int v, int t, int f) {
        if (v == t) return f;
        for (int &i = ptr[v]; i < (int)g[v].size(); i++) {
            int idx = g[v][i];
            if (level[to[idx]] == level[v] + 1 && cap[idx] - flow[idx] > 0) {
                int pushed = dfs(to[idx], t, min(f, cap[idx] - flow[idx]));
                if (pushed > 0) {
                    flow[idx] += pushed;
                    flow[idx ^ 1] -= pushed;
                    return pushed;
                }
            }
        }
        return 0;
    }

    int getMaxFlow(int s, int t) {
        int flow = 0;
        while (bfs(s, t)) {
            memset(ptr, 0, sizeof ptr);
            while (int pushed = dfs(s, t, INF)) {
                flow += pushed;
            }
        }
        return flow;
    }
};

MaxFlow maxFlow;

int n, t;
char a[15][15];
char b[15][15];
int dist[15][15];
bool used[15][15];

bool ok(int x, int y) {
    return 0 <= x && x < n &&
           0 <= y && y < n &&
           a[x][y] != 'Y' &&
           a[x][y] != 'Z';
}

void bfsDeath(int x, int y) {
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            dist[i][j] = INF;

    queue<int> X, Y;
    dist[x][y] = 0;
    X.push(x);
    Y.push(y);

    while (!X.empty()) {
        int curx = X.front();
        int cury = Y.front();
        X.pop(); Y.pop();

        for (int k = 0; k < 4; k++) {
            int tx = curx + dx[k];
            int ty = cury + dy[k];
            if (ok(tx, ty) && dist[tx][ty] == INF) {
                dist[tx][ty] = dist[curx][cury] + 1;
                X.push(tx);
                Y.push(ty);
            }
        }
    }
}

void runBFS(int x, int y) {
    queue<int> X, Y, lev;
    memset(used, false, sizeof used);
    used[x][y] = true;
    X.push(x);
    Y.push(y);
    lev.push(0);

    while (!X.empty()) {
        int curx = X.front();
        int cury = Y.front();
        int curlev = lev.front();
        X.pop(); Y.pop(); lev.pop();

        if (isdigit(b[curx][cury]) && b[curx][cury] != '0') {
            maxFlow.addEdge(x * n + y, sqr(n) + 1 + curx * n + cury, INF);
        }

        if (curlev >= t) continue;

        for (int k = 0; k < 4; k++) {
            int tx = curx + dx[k];
            int ty = cury + dy[k];
            if (ok(tx, ty) && !used[tx][ty]) {
                if (dist[tx][ty] > curlev + 1) {
                    X.push(tx);
                    Y.push(ty);
                    lev.push(curlev + 1);
                } else if (dist[tx][ty] > curlev && isdigit(b[tx][ty]) && b[tx][ty] != '0') {
                    maxFlow.addEdge(x * n + y, sqr(n) + 1 + tx * n + ty, INF);
                }
                used[tx][ty] = true;
            }
        }
    }
}

void build() {
    int posi = -1, posj = -1;
    for (int i = 0; i < n && posi == -1; i++)
        for (int j = 0; j < n && posi == -1; j++)
            if (a[i][j] == 'Z') { posi = i; posj = j; }

    bfsDeath(posi, posj);

    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            if (isdigit(a[i][j]) && a[i][j] != '0')
                maxFlow.addEdge(S, i * n + j, a[i][j] - '0');

    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            if (isdigit(b[i][j]) && b[i][j] != '0')
                maxFlow.addEdge(i * n + j + sqr(n) + 1, T, b[i][j] - '0');

    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            if (isdigit(a[i][j]) && a[i][j] != '0')
                runBFS(i, j);
}

int main() {
#ifndef ONLINE_JUDGE
    freopen("in", "r", stdin);
#endif
    scanf("%d %d", &n, &t);
    scanf("\n");
    for (int i = 0; i < n; i++) gets(a[i]);
    scanf("\n");
    for (int i = 0; i < n; i++) gets(b[i]);
    build();
    printf("%d\n", maxFlow.getMaxFlow(S, T));
    return 0;
}
